def create_file(file_name: str, force: bool = False) -> Path:

    file_path = Path(file_name)

    if file_path.exists():
        if not force:
            print(f"File '{file_name}' "
                  "already exists, do you wish to replace it?")
            answer = input("Y for 'yes', any for 'no': ").strip().lower()
            if answer != "y":
                print("Stopping Program")
                raise FileExistsError(file_name)
            print("Continuing...")
        if file_path.is_file():
            file_path.unlink()
        elif file_path.is_dir():
            if not force:
                print(f"'{file_name}' "
                      "is a directory are you SURE you wish to replace it?")
                answer = input("Y for 'yes', any for 'no': ").strip().lower()
                if answer != "y":
                    print("Stopping Program")
                    raise IsADirectoryError(file_path)
            rmtree(file_path)
        else:
            raise ValueError("Unsupported path type")

    file_path.parent.mkdir(parents=True, exist_ok=True)
    with file_path.open("x"):
        pass

    return file_path

def create_dir(dir_name: str, force: bool = False) -> Path:

    dir_path = Path(dir_name)

    if dir_path.exists():
        if not force:
            print(f"Directory '{dir_name}' "
                  "already exists, do you wish to replace it?")
            answer = input("Y for 'yes', any for 'no': ").strip().lower()
            if answer != "y":
                print("Stopping Program")
                raise FileExistsError(dir_name)
            print("Continuing...")
        if dir_path.is_file():
            if not force:
                print(f"'{dir_name}' "
                      "is a file are you SURE you wish to replace it?")
                answer = input("Y for 'yes', any for 'no': ").strip().lower()
                if answer != "y":
                    print("Stopping Program")
                    raise FileExistsError(dir_path)
            dir_path.unlink()
        elif dir_path.is_dir():
            if not force:
                print(f"'{dir_name}' "
                      "is a directory are you SURE you wish to replace it?")
                answer = input("Y for 'yes', any for 'no': ").strip().lower()
                if answer != "y":
                    print("Stopping Program")
                    raise IsADirectoryError(dir_path)
            rmtree(dir_path)
        else:
            raise ValueError("Unsupported path type")
    dir_path.mkdir(parents=True)

    return dir_path

def ft_repr(s: str) -> str:
    out: str = ""
    for char in s:
        if char in ["\"", "\\"]:
            out += "\\" + char
        elif char == "\n":
            out += "\n"
        elif char == "\t":
            out += "\t"
        elif char == "\0":
            out += "\0"
        elif char == "\v":
            out += "\v"
        else:
            out += char
    return out

